    'ejemplo.meta.titulo': 'Product documentation example · Mireia Gutiérrez Águila',
    'ejemplo.meta.desc': 'An example, with fictitious data, of how I organise product documentation to guide design, development and QA, by Mireia Gutiérrez Águila.',
    'ejemplo.volver': '← Back to Experience',
    'ejemplo.titulo': 'Product documentation example',
    'ejemplo.intro': 'An example, with fictitious data, of how I organise product documentation: one page per feature that guides design, development and QA. Sections expand so you can read only what you need.',
    'ejemplo.nota': 'The example document is in English. Click any screenshot to see it larger.',
    'ejemplo.grupo': 'Document sections',
